template <typename T>
inline auto scaleMultiplier(UInt32 scale)
{
    if constexpr (std::is_same_v<T, Int32> || std::is_same_v<T, Decimal32>)
        return common::exp10_i32(scale);
    else if constexpr (std::is_same_v<T, Int64> || std::is_same_v<T, Decimal64> || std::is_same_v<T, DateTime64> || std::is_same_v<T, Time64>)
        return common::exp10_i64(scale);
    else if constexpr (std::is_same_v<T, Int128> || std::is_same_v<T, Decimal128>)
        return common::exp10_i128(scale);
    else if constexpr (std::is_same_v<T, Int256> || std::is_same_v<T, Decimal256>)
        return common::exp10_i256(scale);
}


/** Components of DecimalX value:
 * whole - represents whole part of decimal, can be negative or positive.
 * fractional - for fractional part of decimal.
 *
 *  0.123 represents  0 /  0.123
 * -0.123 represents  0 / -0.123
 * -1.123 represents -1 /  0.123
 */
template <typename DecimalType>
struct DecimalComponents
{
    using T = typename DecimalType::NativeType;
    T whole;
    T fractional;
};

/// Traits used for determining final Type/Precision/Scale for certain math operations on decimals.
template <typename T>

inline auto binaryOpResult(const DecimalType<T> & tx, const DecimalType<U> & ty)
{
    UInt32 scale{};
    if constexpr (is_multiply)
        scale = tx.getScale() + ty.getScale();
    else if constexpr (is_division)
        scale = tx.getScale();
    else
        scale = (tx.getScale() > ty.getScale() ? tx.getScale() : ty.getScale());

    if constexpr (sizeof(T) < sizeof(U))
        return DataTypeDecimalTrait<U>(DecimalUtils::max_precision<U>, scale);
    else
        return DataTypeDecimalTrait<T>(DecimalUtils::max_precision<T>, scale);
}

template <bool, bool, typename T, typename U, template <typename> typename DecimalType>
inline DataTypeDecimalTrait<T> binaryOpResult(const DecimalType<T> & tx, const DataTypeNumber<U> &)
{
    return DataTypeDecimalTrait<T>(DecimalUtils::max_precision<T>, tx.getScale());
}

template <bool, bool, typename T, typename U, template <typename> typename DecimalType>
inline DataTypeDecimalTrait<U> binaryOpResult(const DataTypeNumber<T> &, const DecimalType<U> & ty)
{
    return DataTypeDecimalTrait<U>(DecimalUtils::max_precision<U>, ty.getScale());
}

if (!arguments.empty() && useDefaultImplementationForNulls())
{
    NullPresence null_presence = getNullPresense(arguments);

    if (null_presence.has_null_constant)
    {
        return makeNullable(std::make_shared<DataTypeNothing>());
    }
    if (null_presence.has_nullable)
    {
        Block nested_columns = createBlockWithNestedColumns(arguments);
        auto return_type = getReturnTypeImpl(ColumnsWithTypeAndName(nested_columns.begin(), nested_columns.end()));
        /// If the return type cannot be Nullable (e.g. Array, Tuple, Map),
        /// return it as-is. For null input rows, the function will be evaluated
        /// over the default values of the nested column and produce the corresponding default result
        /// (e.g. an empty array), instead of failing the type check.
        return makeNullableSafe(return_type);
    }
}

void getLambdaArgumentTypes(DataTypes & arguments) const override
{
    if (arguments.empty())
        throw Exception(
            ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH,
            "Function {} needs at least one argument, passed {}",
            getName(),
            arguments.size());

    if (arguments.size() <= 1 + num_fixed_params)
        throw Exception(
            ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH,
            "Function {} needs at least {} argument{} with data",
            getName(),
            num_fixed_params + 1,
            (num_fixed_params + 1 == 1) ? "" : "s");

    if (arguments.size() > 2 + num_fixed_params && Impl::needOneArray())
        throw Exception(
            ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH,
            "Function {} needs {} argument{} with data",
            getName(),
            num_fixed_params + 1,
            (num_fixed_params + 1 == 1) ? "" : "s");

    bool is_single_array_argument = arguments.size() == num_fixed_params + 2;
    size_t tuple_argument_size = 0;

    size_t num_nested_types = arguments.size() - num_fixed_params - 1;
    DataTypes nested_types(num_nested_types);

    for (size_t i = 0; i < num_nested_types; ++i)
    {
        const auto * array_type = checkAndGetDataType<DataTypeArray>(&*arguments[i + 1 + num_fixed_params]);
        if (!array_type)
            throw Exception(
                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT,
                "Argument {} of function {} must be Array. Found {} instead",
                i + 2 + num_fixed_params,
                getName(),
                arguments[i + 1 + num_fixed_params]->getName());

        if (const auto * tuple_type = checkAndGetDataType<DataTypeTuple>(array_type->getNestedType().get()))
            tuple_argument_size = tuple_type->getElements().size();

        nested_types[i] = recursiveRemoveLowCardinality(array_type->getNestedType());
    }

    const auto * function_type = checkAndGetDataType<DataTypeFunction>(arguments[0].get());
    if (!function_type)
        throw Exception(
            ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT,
            "First argument for this overload of {} must be a function with {} arguments, found {} instead",
            getName(),
            nested_types.size(),
            arguments[0]->getName());

    size_t num_function_arguments = function_type->getArgumentTypes().size();
    if (is_single_array_argument
        && tuple_argument_size > 1
        && tuple_argument_size == num_function_arguments)
    {
        chassert(nested_types.size() == 1);

        auto argument_type = nested_types[0];
        const auto & tuple_type = assert_cast<const DataTypeTuple &>(*argument_type);

        nested_types.clear();
        nested_types.reserve(tuple_argument_size);

        for (const auto & element : tuple_type.getElements())
            nested_types.push_back(element);
    }

    if (num_function_arguments != nested_types.size())
        throw Exception(
            ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT,
            "First argument for this overload of {} must be a function with {} arguments, found {} instead",
            getName(),
            nested_types.size(),
            arguments[0]->getName());

    arguments[0] = std::make_shared<DataTypeFunction>(nested_types);
}

DataTypePtr getReturnTypeImpl(const ColumnsWithTypeAndName & arguments) const override
{
    size_t min_args = (Impl::needExpression() ? 2 : 1) + num_fixed_params ;
    if (arguments.size() < min_args)
        throw Exception(
            ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH,
            "Function {} needs at least {} argument{}, passed {}",
            getName(),
            min_args,
            (min_args > 1 ? "s" : ""),
            arguments.size());

    if (arguments.size() == 1 + num_fixed_params)
    {
        const auto * array_type = checkAndGetDataType<DataTypeArray>(arguments[num_fixed_params].type.get());

        if (!array_type)
            throw Exception(
                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT,
                "The {}{}{} argument for function {} must be array. Found {} instead",
                num_fixed_params + 1,
                getOrdinalSuffix(num_fixed_params + 1),
                (num_fixed_params == 0 ? " and only" : ""),
                getName(),
                arguments[num_fixed_params].type->getName());

        if constexpr (num_fixed_params)
            Impl::checkArguments(getName(), arguments.data());

        DataTypePtr nested_type = array_type->getNestedType();

        if (Impl::needBoolean() && !isUInt8(nested_type))
            throw Exception(
                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT,
                "The {}{}{} argument for function {} must be array of UInt8. Found {} instead",
                num_fixed_params + 1,
                getOrdinalSuffix(num_fixed_params + 1),
                (num_fixed_params == 0 ? " and only" : ""),
                getName(),
                arguments[num_fixed_params].type->getName());

        return Impl::getReturnType(nested_type, nested_type);
    }

    if (arguments.size() > 2 + num_fixed_params && Impl::needOneArray())
        throw Exception(ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH, "Function {} needs one argument with data", getName());

    const auto * data_type_function = checkAndGetDataType<DataTypeFunction>(arguments[0].type.get());

    if (!data_type_function)
        throw Exception(
            ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT,
            "First argument for function {} must be a function. Actual {}",
            getName(),
            arguments[0].type->getName());

    if constexpr (num_fixed_params)
        Impl::checkArguments(getName(), arguments.data() + 1);

    /// The types of the remaining arguments are already checked in getLambdaArgumentTypes.

    DataTypePtr return_type = removeLowCardinality(data_type_function->getReturnType());

    /// Special cases when we need boolean lambda result:
    ///  - lambda may return Nullable(UInt8) column, in this case after lambda execution we will
    ///    replace all NULLs with 0 and return nested UInt8 column.
    ///  - lambda may return Nothing or Nullable(Nothing) because of default implementation of functions
    ///    for these types. In this case we will just create UInt8 const column full of 0.
    if (Impl::needBoolean() && !isUInt8(removeNullable(return_type)) && !isNothing(removeNullable(return_type)))
        throw Exception(
            ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT,
            "Expression for function {} must return UInt8 or Nullable(UInt8), found {}",
            getName(),
            return_type->getName());

    if (arguments.size() < 2 + num_fixed_params)
        throw DB::Exception(ErrorCodes::LOGICAL_ERROR, "Incorrect number of arguments: {}", arguments.size());

    const auto * first_array_type = checkAndGetDataType<DataTypeArray>(arguments[1 + num_fixed_params].type.get());
    if (!first_array_type)
        throw DB::Exception(
            ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT, "Unsupported type {}", arguments[1 + num_fixed_params].type->getName());

    return Impl::getReturnType(return_type, first_array_type->getNestedType());
}

DataTypePtr FieldToDataType<on_error>::operator() (const UInt64 & x) const
{
    if (x <= std::numeric_limits<UInt8>::max()) return std::make_shared<DataTypeUInt8>();
    if (x <= std::numeric_limits<UInt16>::max()) return std::make_shared<DataTypeUInt16>();
    if (x <= std::numeric_limits<UInt32>::max()) return std::make_shared<DataTypeUInt32>();
    if (x <= std::numeric_limits<Int64>::max()) return std::make_shared<DataTypeUInt64>(/*unsigned_can_be_signed=*/true);
    return std::make_shared<DataTypeUInt64>();
}

template <LeastSupertypeOnError on_error>
DataTypePtr FieldToDataType<on_error>::operator() (const Int64 & x) const
{
    if (x <= std::numeric_limits<Int8>::max() && x >= std::numeric_limits<Int8>::min()) return std::make_shared<DataTypeInt8>();
    if (x <= std::numeric_limits<Int16>::max() && x >= std::numeric_limits<Int16>::min()) return std::make_shared<DataTypeInt16>();
    if (x <= std::numeric_limits<Int32>::max() && x >= std::numeric_limits<Int32>::min()) return std::make_shared<DataTypeInt32>();
    return std::make_shared<DataTypeInt64>();
}

template <LeastSupertypeOnError on_error>
DataTypePtr FieldToDataType<on_error>::operator() (const Float64 &) const
{
    return std::make_shared<DataTypeFloat64>();
}

template <LeastSupertypeOnError on_error>

DataTypePtr getNumericType(const TypeIndexSet & types)
{
    bool all_numbers = true;

    size_t max_bits_of_signed_integer = 0;
    size_t max_bits_of_unsigned_integer = 0;
    size_t max_mantissa_bits_of_floating = 0;

    auto maximize = [](size_t & what, size_t value)
    {
        what = std::max(value, what);
    };

    for (const auto & type : types)
    {
        if (type == TypeIndex::UInt8)
            maximize(max_bits_of_unsigned_integer, 8);
        else if (type == TypeIndex::UInt16)
            maximize(max_bits_of_unsigned_integer, 16);
        else if (type == TypeIndex::UInt32 || type == TypeIndex::IPv4)
            maximize(max_bits_of_unsigned_integer, 32);
        else if (type == TypeIndex::UInt64)
            maximize(max_bits_of_unsigned_integer, 64);
        else if (type == TypeIndex::UInt128)
            maximize(max_bits_of_unsigned_integer, 128);
        else if (type == TypeIndex::UInt256)
            maximize(max_bits_of_unsigned_integer, 256);
        else if (type == TypeIndex::Int8 || type == TypeIndex::Enum8)
            maximize(max_bits_of_signed_integer, 8);
        else if (type == TypeIndex::Int16 || type == TypeIndex::Enum16)
            maximize(max_bits_of_signed_integer, 16);
        else if (type == TypeIndex::Int32)
            maximize(max_bits_of_signed_integer, 32);
        else if (type == TypeIndex::Int64)
            maximize(max_bits_of_signed_integer, 64);
        else if (type == TypeIndex::Int128)
            maximize(max_bits_of_signed_integer, 128);
        else if (type == TypeIndex::Int256)
            maximize(max_bits_of_signed_integer, 256);
        else if (type == TypeIndex::BFloat16)
            maximize(max_mantissa_bits_of_floating, 8);
        else if (type == TypeIndex::Float32)
            maximize(max_mantissa_bits_of_floating, 24);
        else if (type == TypeIndex::Float64)
            maximize(max_mantissa_bits_of_floating, 53);
        else if (type != TypeIndex::Nothing)
            all_numbers = false;
    }

    if (max_bits_of_signed_integer || max_bits_of_unsigned_integer || max_mantissa_bits_of_floating)
    {
        if (!all_numbers)
            return throwOrReturn<on_error>(types, "because some of them are numbers and some of them are not", ErrorCodes::NO_COMMON_TYPE);

        /// If there are signed and unsigned types of same bit-width, the result must be signed number with at least one more bit.
        /// Example, common of Int32, UInt32 = Int64.

        size_t min_bit_width_of_integer = std::max(max_bits_of_signed_integer, max_bits_of_unsigned_integer);

        /// If unsigned is not covered by signed.
        if (max_bits_of_signed_integer && max_bits_of_unsigned_integer >= max_bits_of_signed_integer)
        {
            // Because 128 and 256 bit integers are significantly slower, we should not promote to them.
            // But if we already have wide numbers, promotion is necessary.
            if (min_bit_width_of_integer != 64)
                ++min_bit_width_of_integer;
            else
                return throwOrReturn<on_error>(types,
                    "because some of them are signed integers and some are unsigned integers,"
                    " but there is no signed integer type, that can exactly represent all required unsigned integer values",
                    ErrorCodes::NO_COMMON_TYPE);
        }

        /// If the result must be floating.
        if (max_mantissa_bits_of_floating)
        {
            size_t min_mantissa_bits = std::max(min_bit_width_of_integer, max_mantissa_bits_of_floating);
            if (min_mantissa_bits <= 8)
                return std::make_shared<DataTypeBFloat16>();
            else if (min_mantissa_bits <= 24)
                return std::make_shared<DataTypeFloat32>();
            if (min_mantissa_bits <= 53)
                return std::make_shared<DataTypeFloat64>();
            return throwOrReturn<on_error>(
                types,
                " because some of them are integers and some are floating point,"
                " but there is no floating point type, that can exactly represent all required integers",
                ErrorCodes::NO_COMMON_TYPE);
        }

        /// If the result must be signed integer.
        if (max_bits_of_signed_integer)
        {
            if (min_bit_width_of_integer <= 8)
                return std::make_shared<DataTypeInt8>();
            if (min_bit_width_of_integer <= 16)
                return std::make_shared<DataTypeInt16>();
            if (min_bit_width_of_integer <= 32)
                return std::make_shared<DataTypeInt32>();
            if (min_bit_width_of_integer <= 64)
                return std::make_shared<DataTypeInt64>();
            if (min_bit_width_of_integer <= 128)
                return std::make_shared<DataTypeInt128>();
            if (min_bit_width_of_integer <= 256)
                return std::make_shared<DataTypeInt256>();
            return throwOrReturn<on_error>(
                types,
                " because some of them are signed integers and some are unsigned integers,"
                " but there is no signed integer type, that can exactly represent all required unsigned integer values",
                ErrorCodes::NO_COMMON_TYPE);
        }

        /// All unsigned.
        {
            if (min_bit_width_of_integer <= 8)
                return std::make_shared<DataTypeUInt8>();
            if (min_bit_width_of_integer <= 16)
                return std::make_shared<DataTypeUInt16>();
            if (min_bit_width_of_integer <= 32)
                return std::make_shared<DataTypeUInt32>();
            if (min_bit_width_of_integer <= 64)
                return std::make_shared<DataTypeUInt64>();
            if (min_bit_width_of_integer <= 128)
                return std::make_shared<DataTypeUInt128>();
            if (min_bit_width_of_integer <= 256)
                return std::make_shared<DataTypeUInt256>();
            return throwOrReturn<on_error>(
                types,
                " but as all data types are unsigned integers, we must have found maximum unsigned integer type",
                ErrorCodes::NO_COMMON_TYPE);
        }
    }

    return {};
}

/// Check if we can convert UInt64 to Int64 to avoid error "There is no supertype for types UInt64, Int64"
/// during inferring field types.
/// Example:
/// [-3236599669630092879, 5607475129431807682]
/// First field is inferred as Int64, but second one as UInt64, although it also can be Int64.
/// We don't support Int128 as supertype for Int64 and UInt64, because Int128 is inefficient.
/// But in this case the result type can be inferred as Array(Int64).
void convertUInt64toInt64IfPossible(const DataTypes & types, TypeIndexSet & types_set)
{
    /// Check if we have UInt64 and at least one Integer type.
    if (!types_set.contains(TypeIndex::UInt64)
        || (!types_set.contains(TypeIndex::Int8) && !types_set.contains(TypeIndex::Int16) && !types_set.contains(TypeIndex::Int32)
            && !types_set.contains(TypeIndex::Int64)))
        return;

    bool all_uint64_can_be_int64 = true;
    for (const auto & type : types)
    {
        if (const auto * uint64_type = typeid_cast<const DataTypeUInt64 *>(type.get()))
            all_uint64_can_be_int64 &= uint64_type->canUnsignedBeSigned();
    }

    if (all_uint64_can_be_int64)
    {
        types_set.erase(TypeIndex::UInt64);
        types_set.insert(TypeIndex::Int64);
    }
}

DataTypePtr getLeastSuperTypeForTuple(const DataTypes & types)
{
    Strings element_names;
    size_t element_size = 0;
    std::vector<DataTypes> element_types;
    bool initialized = false;

    bool have_nullable = false;

    for (const auto & type : types)
    {
        const IDataType * unwrapped_type = type.get();

        // Unwrap Nullable if present
        if (const auto * nullable_type = typeid_cast<const DataTypeNullable *>(unwrapped_type))
        {
            have_nullable = true;
            unwrapped_type = nullable_type->getNestedType().get();
        }

        if (const auto * type_tuple = typeid_cast<const DataTypeTuple *>(unwrapped_type))
        {
            const auto & current_elements = type_tuple->getElements();
            if (!initialized)
            {
                element_size = current_elements.size();
                element_types.resize(element_size);
                for (size_t i = 0; i < element_size; ++i)
                    element_types[i].reserve(types.size());
                if (type_tuple->hasExplicitNames())
                    element_names = type_tuple->getElementNames();
                initialized = true;
            }

            if (element_size != type_tuple->getElements().size())
                return throwOrReturn<on_error>(types, "because Tuples have different sizes", ErrorCodes::NO_COMMON_TYPE);
            for (size_t i = 0; i < element_size; ++i)
                element_types[i].emplace_back(current_elements[i]);

            // If there are different names, drop all names. The result will be an unnamed tuple.
            if (element_names.empty() == type_tuple->hasExplicitNames())
                element_names.clear();
            if (!element_names.empty())
            {
                const auto & current_element_names = type_tuple->getElementNames();
                for (size_t i = 0; i < element_size; ++i)
                {
                    if (element_names[i] != current_element_names[i])
                    {
                        element_names.clear();
                        break;
                    }
                }
            }
        }
        else if (typeid_cast<const DataTypeNothing *>(unwrapped_type)) /// NULL value (i.e. Nullable(Nothing))
            continue;
        else
            return throwOrReturn<on_error>(types, "because some of them are Tuple and some of them are not", ErrorCodes::NO_COMMON_TYPE);
    }


    DataTypes commont_element_types(element_size);
    for (size_t i = 0; i < element_size; ++i)
    {
        auto common_type = getLeastSupertype<on_error>(element_types[i]);
        /// When on_error == LeastSupertypeOnError::Null and we cannot get least supertype,
        /// common_type will be nullptr, we should return nullptr in this case.
        if (!common_type)
            return nullptr;
        commont_element_types[i] = common_type;
    }

    DataTypePtr result_type;
    if (element_names.empty())
        result_type = std::make_shared<DataTypeTuple>(commont_element_types);
    else
        result_type = std::make_shared<DataTypeTuple>(commont_element_types, element_names);

    if (have_nullable && result_type->canBeInsideNullable())
        result_type = std::make_shared<DataTypeNullable>(result_type);

    return result_type;
}

template <LeastSupertypeOnError on_error>

/// For Arrays
{
    bool have_array = false;
    bool all_arrays = true;

    DataTypes nested_types;
    nested_types.reserve(types.size());

    for (const auto & type : types)
    {
        if (const DataTypeArray * type_array = typeid_cast<const DataTypeArray *>(type.get()))
        {
            have_array = true;
            nested_types.emplace_back(type_array->getNestedType());
        }
        else
            all_arrays = false;
    }

    if (have_array)
    {
        if (!all_arrays)
            return throwOrReturn<on_error>(types, "because some of them are Array and some of them are not", ErrorCodes::NO_COMMON_TYPE);

        auto nested_type = getLeastSupertype<on_error>(nested_types);
        /// When on_error == LeastSupertypeOnError::Null and we cannot get least supertype,
        /// nested_type will be nullptr, we should return nullptr in this case.
        if (!nested_type)
            return nullptr;

        return std::make_shared<DataTypeArray>(nested_type);
    }
}

/// For tuples
{
    bool have_tuple = false;
    for (const auto & type : types)
    {
        const IDataType * unwrapped_type = type.get();

        // Unwrap Nullable if present
        if (const auto * nullable_type = typeid_cast<const DataTypeNullable *>(unwrapped_type))
            unwrapped_type = nullable_type->getNestedType().get();

        if (typeid_cast<const DataTypeTuple *>(unwrapped_type))
        {
            have_tuple = true;
            break;
        }
    }

    if (have_tuple)
        return getLeastSuperTypeForTuple<on_error>(types);
}

/// For maps
{
    bool have_maps = false;
    bool all_maps = true;
    DataTypes key_types;
    DataTypes value_types;
    key_types.reserve(types.size());
    value_types.reserve(types.size());

    for (const auto & type : types)
    {
        if (const DataTypeMap * type_map = typeid_cast<const DataTypeMap *>(type.get()))
        {
            have_maps = true;
            key_types.emplace_back(type_map->getKeyType());
            value_types.emplace_back(type_map->getValueType());
        }
        else
            all_maps = false;
    }

    if (have_maps)
    {
        if (!all_maps)
            return throwOrReturn<on_error>(types, "because some of them are Maps and some of them are not", ErrorCodes::NO_COMMON_TYPE);

        auto keys_common_type = getLeastSupertype<on_error>(key_types);

        auto values_common_type = getLeastSupertype<on_error>(value_types);
        /// When on_error == LeastSupertypeOnError::Null and we cannot get least supertype for keys or values,
        /// keys_common_type or values_common_type will be nullptr, we should return nullptr in this case.
        if (!keys_common_type || !values_common_type)
            return nullptr;

        return std::make_shared<DataTypeMap>(keys_common_type, values_common_type);
    }
}

/// For LowCardinality. This is above Nullable, because LowCardinality can contain Nullable but cannot be inside Nullable.
{
    bool have_low_cardinality = false;
    bool have_not_low_cardinality = false;

    DataTypes nested_types;
    nested_types.reserve(types.size());

    for (const auto & type : types)
    {
        if (const DataTypeLowCardinality * type_low_cardinality = typeid_cast<const DataTypeLowCardinality *>(type.get()))
        {
            have_low_cardinality = true;
            nested_types.emplace_back(type_low_cardinality->getDictionaryType());
        }
        else
        {
            have_not_low_cardinality = true;
            nested_types.emplace_back(type);
        }
    }

    /// All LowCardinality gives LowCardinality.
    /// LowCardinality with high cardinality gives high cardinality.
    if (have_low_cardinality)
    {
        if (have_not_low_cardinality)
            return getLeastSupertype<on_error>(nested_types);

        auto nested_type = getLeastSupertype<on_error>(nested_types);

        /// When on_error == LeastSupertypeOnError::Null and we cannot get least supertype,
        /// nested_type will be nullptr, we should return nullptr in this case.
        if (!nested_type)
            return nullptr;
        return std::make_shared<DataTypeLowCardinality>(nested_type);
    }
}

/// For Nullable
{
    bool have_nullable = false;

    DataTypes nested_types;
    nested_types.reserve(types.size());

    for (const auto & type : types)
    {
        if (const DataTypeNullable * type_nullable = typeid_cast<const DataTypeNullable *>(type.get()))
        {
            have_nullable = true;

            if (!type_nullable->onlyNull())
                nested_types.emplace_back(type_nullable->getNestedType());
        }
        else
            nested_types.emplace_back(type);
    }

    if (have_nullable)
    {
        auto nested_type = getLeastSupertype<on_error>(nested_types);
        /// When on_error == LeastSupertypeOnError::Null and we cannot get least supertype,
        /// nested_type will be nullptr, we should return nullptr in this case.
        if (!nested_type)
            return nullptr;
        /// Common type for Nullable(Nothing) and Variant(...) is Variant(...)
        if (isVariant(nested_type))
            return nested_type;
        return std::make_shared<DataTypeNullable>(nested_type);
    }
}

